-- Read-only post-check for 20270102130000_editions_stripe_lifecycle.sql. Every row should say ok = true.
select 'cancel queue exists with RLS on' as check, count(*) = 1 as ok from pg_class where relname = 'edition_stripe_cancel_queue' and relrowsecurity;
select 'cancel queue is not readable or writable by users' as check, count(*) = 0 as ok from information_schema.role_table_grants where table_name = 'edition_stripe_cancel_queue' and grantee in ('anon', 'authenticated', 'public');
select 'queue functions are not callable by users' as check, count(*) = 0 as ok from pg_proc p where proname in ('edition_stripe_cancel_enqueue', 'edition_stripe_cancels_next', 'edition_stripe_cancel_mark', 'edition_membership_stripe_cancel_trg') and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'));
select 'cancel trigger is on organiser_memberships' as check, count(*) = 1 as ok from pg_trigger where tgrelid = 'public.organiser_memberships'::regclass and tgname = 'zz_edition_membership_stripe_cancel' and not tgisinternal;
select 'exception kinds include payment_after_cancel and duplicate_payment' as check, count(*) = 1 as ok from pg_constraint where conrelid = 'public.edition_reconciliation_exceptions'::regclass and contype = 'c' and pg_get_constraintdef(oid) like '%payment_after_cancel%' and pg_get_constraintdef(oid) like '%duplicate_payment%';
select 'no card membership that is cancelled/withdrawn/declined still lacks a queued cancel' as check, count(*) = 0 as ok from public.organiser_memberships m where m.stripe_subscription_id is not null and m.status in ('cancelled', 'withdrawn', 'declined') and not exists (select 1 from public.edition_stripe_cancel_queue q where q.membership_id = m.id);
